var STATUSES = ['Proposed', 'Approved', 'Implemented', 'Verified', 'Deleted', 'Rejected'];

function statusReport(reqs) {
  var counts = {};
  STATUSES.forEach(function (s) { counts[s] = 0; });
  var invalid = [];
  reqs.forEach(function (r) {
    if (STATUSES.indexOf(r.status) >= 0) counts[r.status]++;
    else invalid.push(r.id);
  });
  var active = counts.Proposed + counts.Approved + counts.Implemented + counts.Verified;
  var percentDone = active ? Math.round(counts.Verified * 100 / active) : 0;
  return { counts: counts, percentDone: percentDone, invalid: invalid.sort() };
}
